import React, { useState, useEffect, useCallback, useMemo } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Grid,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Chip,
  Alert,
  CircularProgress,
  Paper,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Divider,
  IconButton,
  Accordion,
  AccordionSummary,
  AccordionDetails,
} from '@mui/material';
import { useTheme } from '@mui/material/styles';
import ApiService from '../services/api';
import {
  Info as InfoIcon,
  Refresh as RefreshIcon,
  Timeline as TimelineIcon,
  ExpandMore as ExpandMoreIcon,
} from '@mui/icons-material';
import {
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as RechartsTooltip,
  Legend,
  ResponsiveContainer,
  Area,
  AreaChart,
  ReferenceLine,
} from 'recharts';
import {
  axisTickForMode,
  cartesianGridStroke,
  chartAnimationPropsFor,
  rechartsLegendProps,
  rechartsTooltipProps,
} from '../theme/rechartsAppearances';
import {
  CO2E_METHODOLOGY_SUBTITLE,
  formatAxisTickKg,
  formatCo2eFromKg,
  yAxisLabelForKgDomain,
} from '../constants/carbonVisualization';
import { usePrefersReducedMotion } from '../hooks/usePrefersReducedMotion';
import WorkspacePageHeader from './shared/WorkspacePageHeader';

interface ForecastData {
  period: number;
  date: string;
  year: number;
  month: number;
  totalCO2: number;
  confidenceInterval: {
    lower: number;
    upper: number;
  };
  breakdown: any;
  carbonScore: number;
  esgScopes: any;
}

interface HistoricalData {
  period: number;
  date: string;
  year: number;
  month: number;
  totalCO2: number;
  breakdown: any;
  carbonScore: number;
  esgScopes: any;
}

interface ForecastResponse {
  historical: HistoricalData[];
  current: HistoricalData[];
  forecast: {
    data: ForecastData[];
    parameters: any;
    model: string;
  };
  accuracy: {
    mape: number;
    rmse: number;
    mae: number;
  };
  insights: Array<{
    type: string;
    title: string;
    description: string;
    priority: string;
    impact: number;
  }>;
  model: {
    type: string;
    parameters: any;
  };
}

const formatAccuracyNumber = (value: unknown, suffix = ''): string => {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return `${value.toFixed(1)}${suffix}`;
  }
  return '—';
};


const averageCo2FromPoints = (points?: Array<{ totalCO2?: number }> | null): number | null => {
  if (!points || points.length === 0) return null;
  const sum = points.reduce((acc, row) => acc + (Number(row.totalCO2) || 0), 0);
  return sum / points.length;
};

/** Same rule as the Forecast Summary warning: no usable next-year projection. */
const isForecastProjectionUnusable = (data: ForecastResponse | null | undefined): boolean => {
  if (!data) return true;
  const projected = averageCo2FromPoints(data.forecast?.data);
  const historicalAvg = averageCo2FromPoints(data.historical?.slice(-12));
  return projected == null || (projected === 0 && historicalAvg != null && historicalAvg > 0);
};

const finiteCo2 = (value: unknown): number | null => {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : null;
};

type ForecastChartRow = {
  date: string;
  type: 'Historical' | 'Forecast';
  historicalCO2: number | null;
  forecastCO2: number | null;
  lowerBound: number | null;
  upperBound: number | null;
  bandBase: number | null;
  bandSpan: number | null;
};

const confidenceBandDisplay = (lower: number | null, upper: number | null) => {
  if (lower == null || upper == null) {
    return { bandBase: null as number | null, bandSpan: null as number | null };
  }
  const ceiling = Math.max(lower, upper);
  if (ceiling <= 0) {
    return { bandBase: null, bandSpan: null };
  }
  const bandBase = Math.max(0, Math.min(lower, upper));
  return { bandBase, bandSpan: Math.max(0, ceiling - bandBase) };
};

const ForecastChartTooltip: React.FC<{
  active?: boolean;
  payload?: Array<{ payload?: ForecastChartRow }>;
  label?: string | number;
  contentStyle?: React.CSSProperties;
  labelStyle?: React.CSSProperties;
  itemStyle?: React.CSSProperties;
}> = ({ active, payload, label, contentStyle, labelStyle, itemStyle }) => {
  if (!active || !payload?.length) return null;
  const row = payload[0]?.payload;
  if (!row) return null;
  const lines: Array<{ name: string; value: string }> = [];
  if (typeof row.historicalCO2 === 'number') {
    lines.push({ name: 'Historical', value: formatCo2eFromKg(row.historicalCO2) });
  }
  if (typeof row.forecastCO2 === 'number') {
    lines.push({ name: 'Forecast', value: formatCo2eFromKg(row.forecastCO2) });
  }
  if (row.lowerBound != null && row.upperBound != null) {
    lines.push({
      name: 'Confidence',
      value: `${formatCo2eFromKg(row.lowerBound)} – ${formatCo2eFromKg(row.upperBound)}`,
    });
  }
  if (!lines.length) return null;
  return (
    <div style={contentStyle}>
      <div style={labelStyle}>{`Period: ${label}`}</div>
      {lines.map((line) => (
        <div key={line.name} style={itemStyle}>{`${line.name}: ${line.value}`}</div>
      ))}
    </div>
  );
};

const CarbonForecastingGraph: React.FC = () => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';
  const gridStroke = cartesianGridStroke(isDark);
  const tickStyle = axisTickForMode(isDark);
  const tooltipProps = rechartsTooltipProps(isDark);
  const chartMotion = chartAnimationPropsFor(usePrefersReducedMotion());

  const [forecastData, setForecastData] = useState<ForecastResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [forecastPeriods, setForecastPeriods] = useState(12);
  const [modelType, setModelType] = useState('auto');
  const [confidenceLevel, setConfidenceLevel] = useState(0.95);

  const loadForecastData = useCallback(async () => {
    setLoading(true);
    setError(null);
    
    try {
      const result = await ApiService.getCarbonForecast({
        forecastPeriods,
        modelType,
        confidenceLevel,
      });

      if (result && typeof result === 'object' && 'success' in result && result.success) {
        setForecastData((result as { data: ForecastResponse }).data);
      } else if (result && typeof result === 'object' && 'data' in result) {
        setForecastData((result as { data: ForecastResponse }).data);
      } else {
        throw new Error(
          (result as { message?: string })?.message || 'Failed to generate forecast'
        );
      }
    } catch (err) {
      console.error('Error loading forecast data:', err);
      setError(err instanceof Error ? err.message : 'Failed to load forecast data');
    } finally {
      setLoading(false);
    }
  }, [forecastPeriods, modelType, confidenceLevel]);

  useEffect(() => {
    loadForecastData();
  }, [loadForecastData]);

  const projectionUnusable = isForecastProjectionUnusable(forecastData);

  const chartData = useMemo(() => {
    if (!forecastData) return [] as ForecastChartRow[];

    const historical: ForecastChartRow[] = (forecastData.historical ?? []).map((item) => ({
      date: new Date(item.date).toLocaleDateString('en-US', { month: 'short', year: 'numeric' }),
      type: 'Historical' as const,
      historicalCO2: finiteCo2(item.totalCO2),
      forecastCO2: null,
      lowerBound: null,
      upperBound: null,
      bandBase: null,
      bandSpan: null,
    }));

    if (isForecastProjectionUnusable(forecastData)) {
      return historical;
    }

    const forecast: ForecastChartRow[] = (forecastData.forecast?.data ?? []).map((item) => {
      const lowerBound = finiteCo2(item.confidenceInterval?.lower);
      const upperBound = finiteCo2(item.confidenceInterval?.upper);
      const band = confidenceBandDisplay(lowerBound, upperBound);
      return {
        date: new Date(item.date).toLocaleDateString('en-US', { month: 'short', year: 'numeric' }),
        type: 'Forecast' as const,
        historicalCO2: null,
        forecastCO2: finiteCo2(item.totalCO2),
        lowerBound,
        upperBound,
        bandBase: band.bandBase,
        bandSpan: band.bandSpan,
      };
    });

    return [...historical, ...forecast];
  }, [forecastData]);

  const forecastBoundaryX = useMemo(() => {
    const first = chartData.find((row) => row.type === 'Forecast');
    return first?.date;
  }, [chartData]);

  const chartYMax = useMemo(() => {
    let seriesMax = 1;
    chartData.forEach((row) => {
      [row.historicalCO2, row.forecastCO2].forEach((value) => {
        if (typeof value === 'number' && value > 0) {
          seriesMax = Math.max(seriesMax, value);
        }
      });
    });
    return seriesMax <= 1 ? 1 : seriesMax * 1.08;
  }, [chartData]);

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high':
        return 'error';
      case 'medium':
        return 'warning';
      case 'low':
        return 'success';
      default:
        return 'default';
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <CircularProgress size={60} />
        <Typography variant="h6" sx={{ ml: 2 }}>
          Generating carbon footprint forecast...
        </Typography>
      </Box>
    );
  }

  if (error) {
    return (
      <Alert severity="error" sx={{ mb: 2 }}>
        {error}
        <IconButton onClick={loadForecastData} sx={{ ml: 1 }}>
          <RefreshIcon />
        </IconButton>
      </Alert>
    );
  }

  return (
    <Box>
      <WorkspacePageHeader
        title="Carbon forecasting"
        description={`Forward projection of this company's footprint. Past intensity stays on Analytics. ${CO2E_METHODOLOGY_SUBTITLE}`}
      />

      {/* Controls */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Grid container spacing={3} alignItems="center">
            <Grid item xs={12} sm={4}>
              <FormControl fullWidth>
                <InputLabel>Forecast Period</InputLabel>
                <Select
                  value={forecastPeriods}
                  onChange={(e) => setForecastPeriods(Number(e.target.value))}
                  label="Forecast Period"
                >
                  <MenuItem value={6}>6 Months</MenuItem>
                  <MenuItem value={12}>12 Months</MenuItem>
                  <MenuItem value={18}>18 Months</MenuItem>
                  <MenuItem value={24}>24 Months</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={4}>
              <FormControl fullWidth>
                <InputLabel>Model Type</InputLabel>
                <Select
                  value={modelType}
                  onChange={(e) => setModelType(e.target.value)}
                  label="Model Type"
                >
                  <MenuItem value="auto">Auto Select</MenuItem>
                  <MenuItem value="linear">Linear Regression</MenuItem>
                  <MenuItem value="exponential">Exponential Smoothing</MenuItem>
                  <MenuItem value="movingAverage">Moving Average</MenuItem>
                  <MenuItem value="arima">ARIMA</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={4}>
              <FormControl fullWidth>
                <InputLabel>Confidence Level</InputLabel>
                <Select
                  value={confidenceLevel}
                  onChange={(e) => setConfidenceLevel(Number(e.target.value))}
                  label="Confidence Level"
                >
                  <MenuItem value={0.90}>90%</MenuItem>
                  <MenuItem value={0.95}>95%</MenuItem>
                  <MenuItem value={0.99}>99%</MenuItem>
                </Select>
              </FormControl>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {forecastData && (
        <Grid container spacing={3}>
          {/* Main Chart */}
          <Grid item xs={12} lg={8}>
            <Card>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 1, flexWrap: 'wrap', gap: 1 }}>
                  <TimelineIcon sx={{ mr: 1 }} />
                  <Typography variant="h6">
                    Carbon Footprint Forecast
                  </Typography>
                  <Chip
                    label={(forecastData.model?.type || forecastData.forecast?.model || 'AUTO').toString().toUpperCase()}
                    size="small"
                    sx={{ ml: 2 }}
                    color="primary"
                  />
                </Box>
                <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
                  {projectionUnusable
                    ? 'History only. The summary states when a next-year projection is not available.'
                    : 'Vertical marker separates fitted history from projected periods. Shaded band is the model confidence interval.'}
                </Typography>

                <Box
                  role="img"
                  aria-label={projectionUnusable
                    ? 'Area chart of historical carbon dioxide equivalent emissions. No usable forecast is drawn.'
                    : 'Area chart of historical and forecast carbon dioxide equivalent emissions with confidence band.'}
                  sx={{ width: '100%', height: 400 }}
                >
                  <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={chartData} margin={{ top: 12, right: 16, left: 8, bottom: 8 }}>
                    <defs>
                      <linearGradient id="forecastHistFill" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#2563eb" stopOpacity={0.45} />
                        <stop offset="95%" stopColor="#2563eb" stopOpacity={0.04} />
                      </linearGradient>
                      <linearGradient id="forecastProjFill" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#ea580c" stopOpacity={0.35} />
                        <stop offset="100%" stopColor="#ea580c" stopOpacity={0.03} />
                      </linearGradient>
                      <linearGradient id="forecastBandFill" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#f59e0b" stopOpacity={0.28} />
                        <stop offset="100%" stopColor="#f59e0b" stopOpacity={0.08} />
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} vertical={false} />
                    <XAxis
                      dataKey="date"
                      tick={tickStyle}
                      angle={-40}
                      textAnchor="end"
                      height={88}
                      interval="preserveStartEnd"
                    />
                    <YAxis
                      domain={[0, chartYMax]}
                      allowDataOverflow
                      label={{
                        value: yAxisLabelForKgDomain(chartYMax),
                        angle: -90,
                        position: 'insideLeft',
                        fill: tickStyle.fill,
                        fontSize: 12,
                      }}
                      tick={tickStyle}
                      tickFormatter={(v: number) => formatAxisTickKg(v)}
                    />
                    <RechartsTooltip
                      {...tooltipProps}
                      content={(tooltipContent) => (
                        <ForecastChartTooltip
                          active={tooltipContent.active}
                          payload={tooltipContent.payload as Array<{ payload?: ForecastChartRow }> | undefined}
                          label={tooltipContent.label}
                          contentStyle={tooltipProps.contentStyle}
                          labelStyle={tooltipProps.labelStyle}
                          itemStyle={tooltipProps.itemStyle}
                        />
                      )}
                    />
                    <Legend {...rechartsLegendProps} />

                    {!projectionUnusable ? (
                      <Area
                        type="monotone"
                        dataKey="bandBase"
                        stackId="confidence"
                        stroke="none"
                        fill="transparent"
                        name="Confidence base"
                        legendType="none"
                        connectNulls={false}
                        {...chartMotion}
                      />
                    ) : null}
                    {!projectionUnusable ? (
                      <Area
                        type="monotone"
                        dataKey="bandSpan"
                        stackId="confidence"
                        stroke="none"
                        fill="url(#forecastBandFill)"
                        name="Confidence band"
                        connectNulls={false}
                        {...chartMotion}
                      />
                    ) : null}

                    <Area
                      type="monotone"
                      dataKey="historicalCO2"
                      stroke="#1d4ed8"
                      strokeWidth={2}
                      fill="url(#forecastHistFill)"
                      name="Historical"
                      connectNulls={false}
                      {...chartMotion}
                    />

                    {!projectionUnusable ? (
                      <Area
                        type="monotone"
                        dataKey="forecastCO2"
                        stroke="#c2410c"
                        strokeWidth={2}
                        fill="url(#forecastProjFill)"
                        name="Forecast"
                        strokeDasharray="6 4"
                        connectNulls={false}
                        {...chartMotion}
                      />
                    ) : null}

                    {forecastBoundaryX && (
                      <ReferenceLine
                        x={forecastBoundaryX}
                        stroke="#f43f5e"
                        strokeDasharray="4 4"
                        strokeWidth={1.5}
                        label={{
                          value: 'Forecast start',
                          position: 'top',
                          fill: tickStyle.fill,
                          fontSize: 11,
                        }}
                      />
                    )}
                  </AreaChart>
                </ResponsiveContainer>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          {/* Forecast Summary */}
          <Grid item xs={12} lg={4}>
            <Card sx={{ mb: 3 }}>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Forecast Summary
                </Typography>

                <Accordion disableGutters elevation={0} sx={{ '&:before': { display: 'none' }, mb: 1 }}>
                  <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                    <Typography variant="subtitle2">Model accuracy (MAPE, RMSE, MAE)</Typography>
                  </AccordionSummary>
                  <AccordionDetails>
                    <Box sx={{ mb: 1 }}>
                      <Typography variant="body2" color="text.secondary">
                        MAPE
                      </Typography>
                      <Typography variant="body1">{formatAccuracyNumber(forecastData?.accuracy?.mape, '%')}</Typography>
                    </Box>
                    <Box sx={{ mb: 1 }}>
                      <Typography variant="body2" color="text.secondary">
                        RMSE (kg CO₂e)
                      </Typography>
                      <Typography variant="body1">{formatAccuracyNumber(forecastData?.accuracy?.rmse)}</Typography>
                    </Box>
                    <Box>
                      <Typography variant="body2" color="text.secondary">
                        MAE (kg CO₂e)
                      </Typography>
                      <Typography variant="body1">{formatAccuracyNumber(forecastData?.accuracy?.mae)}</Typography>
                    </Box>
                  </AccordionDetails>
                </Accordion>

                <Divider sx={{ my: 2 }} />
                
                <Box sx={{ mb: 2 }}>
                  <Typography variant="body2" color="text.secondary">
                    Current Year Average
                  </Typography>
                  <Typography variant="h6">
                    {(() => {
                      const currentAvg = averageCo2FromPoints(forecastData.current);
                      const historicalAvg = averageCo2FromPoints(forecastData.historical?.slice(-12));
                      const value = currentAvg ?? historicalAvg;
                      if (value == null) return '—';
                      return formatCo2eFromKg(value);
                    })()}
                  </Typography>
                  {(forecastData.current?.length ?? 0) === 0 && (forecastData.historical?.length ?? 0) > 0 ? (
                    <Typography variant="caption" color="text.secondary">
                      No points tagged to this calendar year — showing recent historical average.
                    </Typography>
                  ) : null}
                </Box>
                
                <Box sx={{ mb: 2 }}>
                  <Typography variant="body2" color="text.secondary">
                    Projected Next Year Average
                  </Typography>
                  <Typography variant="h6">
                    {projectionUnusable
                      ? '—'
                      : formatCo2eFromKg(averageCo2FromPoints(forecastData.forecast?.data) ?? 0)}
                  </Typography>
                  {projectionUnusable ? (
                    <Typography variant="caption" color="warning.main" display="block">
                      Confidence band / period count above are model settings only — no usable next-year projection
                      from current inventory history yet.
                    </Typography>
                  ) : null}
                </Box>
              </CardContent>
            </Card>

            {/* Insights */}
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Forecast Insights
                </Typography>
                
                {(forecastData.insights?.length ?? 0) > 0 ? (
                  <List dense>
                    {(forecastData.insights ?? []).map((insight, index) => (
                      <ListItem key={index}>
                        <ListItemIcon>
                          <InfoIcon color={getPriorityColor(insight.priority) as any} />
                        </ListItemIcon>
                        <ListItemText
                          primary={insight.title}
                          secondary={insight.description}
                        />
                        <Chip
                          label={insight.priority}
                          size="small"
                          color={getPriorityColor(insight.priority) as any}
                        />
                      </ListItem>
                    ))}
                  </List>
                ) : (
                  <Typography variant="body2" color="text.secondary">
                    No specific insights available for this forecast.
                  </Typography>
                )}
              </CardContent>
            </Card>
          </Grid>

          {/* Historical vs Forecast Comparison */}
          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Historical vs Forecast Comparison
                </Typography>
                
                <Grid container spacing={3}>
                  <Grid item xs={12} md={4}>
                    <Paper sx={{ p: 2, textAlign: 'center' }}>
                      <Typography variant="h4" color="primary">
                        {forecastData.historical?.length ?? 0}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Historical Data Points
                      </Typography>
                    </Paper>
                  </Grid>
                  
                  <Grid item xs={12} md={4}>
                    <Paper sx={{ p: 2, textAlign: 'center' }}>
                      <Typography variant="h4" color="warning.main">
                        {forecastData.forecast?.data?.length ?? 0}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Forecast Periods
                      </Typography>
                    </Paper>
                  </Grid>
                  
                  <Grid item xs={12} md={4}>
                    <Paper sx={{ p: 2, textAlign: 'center' }}>
                      <Typography variant="h4" color="success.main">
                        {forecastData.current?.length ?? 0}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Current Year Data Points
                      </Typography>
                    </Paper>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}
    </Box>
  );
};

export default CarbonForecastingGraph;